import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"关于","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/user-guide/settings/about.md","filePath":"zh-CN/user-guide/settings/about.md","lastUpdated":1786082398000}'),s={name:"zh-CN/user-guide/settings/about.md"};function n(i,e,l,d,c,u){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h1><p>显示 App、Core、Service、CLI 四个组件的版本号(颜色会反映服务当前是否健康)、Lertaro 的简短说明，以及项目主页和在线使用手册的链接。</p><h2 id="数据目录" tabindex="-1">数据目录 <a class="header-anchor" href="#数据目录" aria-label="Permalink to &quot;数据目录&quot;">​</a></h2><p>紧接着下方还有两个链接，用来打开 Lertaro 读写自身配置的文件夹——链接文字本身就是实际路径，点击时如果文件夹还不存在会先创建出来:</p><ul><li><strong>用户数据目录</strong> —— 存放 <code>user-settings.json</code> 的每用户目录。每次保存设置时，都会先把当前文件轮转备份为 <code>user-settings.json.bak.1</code>(旧的备份依次往后顺延，最多保留到 <code>.bak.5</code>)，再写入新文件，所以一次误改或者保存过程中崩溃，总能找到一份最近的备份恢复。搜索历史、证书和用户专属缓存也保存在这里。</li><li><strong>机器数据目录</strong> —— 后台服务使用的机器级目录(<code>machine-settings.json</code>、本地磁盘索引缓存，以及服务端日志)。</li></ul><p>安装版使用 <code>%LocalAppData%\\Lertaro</code> 和 <code>%ProgramData%\\Lertaro</code>。便携版在程序旁使用 <code>Data\\Users\\&lt;SID hash&gt;</code> 和 <code>Data\\Machine</code>;如果便携版的 <code>Data</code> 目录尚未创建，为了兼容会复用已有的安装版数据。目录优先级请参阅<a href="./../getting-started.html#便携版数据">便携版数据</a>。</p><h2 id="检查更新" tabindex="-1">检查更新 <a class="header-anchor" href="#检查更新" aria-label="Permalink to &quot;检查更新&quot;">​</a></h2><ul><li><strong>检查更新</strong> 按钮 —— 查询是否有新版本;按钮文字本身会反映进度(&quot;正在检查更新...&quot;，之后显示 &quot;已是最新版本&quot;或找到的新版本号)。</li><li>如果非管理员账户无法停止后台服务来原地安装更新，会显示一条警告横幅，并引导你前往手动下载页面。</li><li>一旦发现新版本: <ul><li><strong>静默自动更新</strong> —— 后台下载安装，显示进度条，完成后自动重启 Lertaro。</li><li><strong>前往下载页面</strong> —— 在浏览器中打开 GitHub release 页面，手动安装。</li></ul></li></ul><p>这个页面和<a href="./general.html#系统">通用 → 系统</a>里的<strong>启动时自动检查更新</strong> / <strong>自动静默更新</strong>两个复选框是配套的——那两项控制是否在启动时自动执行这次检查;这个页面则是让你随时手动触发一次。</p>',9)])])}const p=t(s,[["render",n]]);export{h as __pageData,p as default};
